style.css:
@-moz-document domain("youtube.com") {
html:has(ytd-app) {
    color-scheme: dark !important;
    background: #040807 !important;
  }

  html:has(ytd-app) body {
    background:
      radial-gradient(ellipse at 18% 8%, rgba(16, 72, 56, .34), transparent 46%),
      radial-gradient(ellipse at 82% 18%, rgba(14, 58, 74, .24), transparent 42%),
      radial-gradient(ellipse at 50% 90%, rgba(12, 42, 36, .28), transparent 50%),
      linear-gradient(155deg, #040807, #07110e 55%, #040807) !important;
    color: #cde3dc !important;
  }

  /* Main YouTube surfaces */
  html:has(ytd-app) ytd-app,
  html:has(ytd-app) #content,
  html:has(ytd-app) ytd-watch-flexy,
  html:has(ytd-app) #primary,
  html:has(ytd-app) #secondary,
  html:has(ytd-app) ytd-browse,
  html:has(ytd-app) ytd-two-column-browse-results-renderer,
  html:has(ytd-app) #page-manager {
    background: transparent !important;
  }

  /* Deep smoked-emerald glass panels */
  html:has(ytd-app) ytd-masthead,
  html:has(ytd-app) #guide-content,
  html:has(ytd-app) ytd-mini-guide-renderer,
  html:has(ytd-app) ytd-rich-section-renderer,
  html:has(ytd-app) ytd-playlist-panel-renderer,
  html:has(ytd-app) #chat,
  html:has(ytd-app) #comments {
    background: rgba(8, 18, 15, .84) !important;
    backdrop-filter: blur(18px) saturate(125%) !important;
    -webkit-backdrop-filter: blur(18px) saturate(125%) !important;
    border-color: rgba(68, 148, 122, .14) !important;
  }

  /* Search bar */
  html:has(ytd-app) #center {
    background: transparent !important;
  }

  html:has(ytd-app) ytd-searchbox,
  html:has(ytd-app) #search-form {
    background: rgba(10, 22, 18, .85) !important;
    border: 1px solid rgba(64, 138, 114, .24) !important;
    border-radius: 24px !important;
  }

  html:has(ytd-app) #search {
    color: #d8ece5 !important;
  }

  /* Video cards */
  html:has(ytd-app) ytd-rich-item-renderer,
  html:has(ytd-app) ytd-video-renderer,
  html:has(ytd-app) ytd-compact-video-renderer,
  html:has(ytd-app) ytd-grid-video-renderer {
    border-radius: 16px !important;
    transition: background .2s ease, transform .2s ease !important;
  }

  html:has(ytd-app) ytd-rich-item-renderer:hover,
  html:has(ytd-app) ytd-video-renderer:hover,
  html:has(ytd-app) ytd-compact-video-renderer:hover {
    background: rgba(34, 92, 74, .16) !important;
  }

  /* Thumbnails */
  html:has(ytd-app) ytd-thumbnail,
  html:has(ytd-app) yt-image {
    border-radius: 14px !important;
    overflow: hidden !important;
  }

  /* Soft sage-white text */
  html:has(ytd-app) #video-title,
  html:has(ytd-app) .title,
  html:has(ytd-app) #channel-name,
  html:has(ytd-app) #owner-text,
  html:has(ytd-app) #description,
  html:has(ytd-app) #description-text,
  html:has(ytd-app) #description-inline-expander {
    color: #cde3dc !important;
  }

  /* Secondary text */
  html:has(ytd-app) #metadata-line,
  html:has(ytd-app) #metadata,
  html:has(ytd-app) .inline-metadata-item,
  html:has(ytd-app) #subtitle,
  html:has(ytd-app) yt-formatted-string[secondary] {
    color: #7ea397 !important;
  }

  /* Buttons */
  html:has(ytd-app) yt-button-shape button,
  html:has(ytd-app) ytd-button-renderer button,
  html:has(ytd-app) #top-level-buttons-computed button {
    border-radius: 22px !important;
    transition: background .2s ease, box-shadow .2s ease !important;
  }

  html:has(ytd-app) yt-button-shape button:hover,
  html:has(ytd-app) ytd-button-renderer button:hover {
    background: rgba(42, 110, 88, .22) !important;
  }

  /* Muted emerald Subscribe button */
  html:has(ytd-app) ytd-subscribe-button-renderer button {
    background: linear-gradient(115deg, #1d5c49, #1b5266) !important;
    color: #e2f5ee !important;
    border: 1px solid rgba(82, 176, 146, .25) !important;
    border-radius: 22px !important;
  }

  html:has(ytd-app) ytd-subscribe-button-renderer button:hover {
    background: linear-gradient(115deg, #24735b, #226680) !important;
  }

  /* Player */
  html:has(ytd-app) .html5-video-player {
    border-radius: 16px !important;
    overflow: hidden !important;
    background: #030605 !important;
  }

  /* Scrollbars */
  html:has(ytd-app) * {
    scrollbar-color: #244d40 #060c0a;
    scrollbar-width: thin;
  }

  html:has(ytd-app) ::selection {
    background: rgba(38, 115, 90, .55) !important;
    color: #e2f5ee !important;
  }
}
